"""Generated files in a project: CLAUDE.md (rules, written once) and state.md (the state table, rewritten often)."""

import datetime as dt

from .project import ENGINE
from .state import STEPS, State

MARK = "<!-- generated by translator; edit templates/CLAUDE.md in the engine, not this file -->"


def claude_md(project, force=False):
    p = project.root / "CLAUDE.md"
    if p.exists() and MARK not in p.read_text(encoding="utf-8") and not force:
        return False          # a hand-written CLAUDE.md is left alone
    book = project.cfg.get("book") or {}
    text = (ENGINE / "templates" / "CLAUDE.md").read_text(encoding="utf-8")
    text = text.replace("{{MARK}}", MARK).replace("{{TITLE}}", project.title)
    text = text.replace("{{AUTHOR}}", book.get("author") or "author to confirm").replace("{{HOUSE}}", project.cfg.get("house", "koren"))
    p.write_text(text, encoding="utf-8")
    return True


def state_md(project, state=None):
    state = state or State(project)
    rows = ["| Unit | Title | Last step passed | Waiting for |", "| --- | --- | --- | --- |"]
    for u in project.units:
        rows.append(f"| {u['id']} | {u.get('title', '')} | {state.last_passed(u['id']) or '—'} | {state.waiting_for(u['id'])} |")
    tor = state.data.get("text_of_record", {})
    word = [k for k, v in tor.items() if k != "default" and v == "word"]
    lines = [f"## State (generated {dt.datetime.now():%Y-%m-%d %H:%M})", "",
             "Text of record: chapter files" + (f", except {', '.join(word)} (Word masters: run /import first)." if word else "."),
             "", *rows, "", f"Steps, in order: {' → '.join(STEPS)}.", ""]
    (project.root / "state.md").write_text("\n".join(lines), encoding="utf-8")
